<script setup lang="ts">
/**
 * A vertical sequence of dated events (`design/components/timeline.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/timeline.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/timeline.module.css'

export type TimelineTone = 'neutral' | 'accent' | 'info' | 'success' | 'warning' | 'danger'

export interface TimelineEvent {
  title: string
  time: string
  detail?: string
  icon?: IconRole
  tone?: TimelineTone
}

export interface TimelineProps {
  /**
   * Events in reading order; Timeline never sorts them.
   */
  events: TimelineEvent[]
  /**
   * The list's accessible name, such as "Ticket history" rather than "Timeline".
   */
  label: string
}

defineOptions({ name: 'Timeline', inheritAttrs: false })

defineProps<TimelineProps>()
</script>

<template>
  <ol v-if="events.length > 0" :class="styles.root" :aria-label="label" data-member="timeline">
    <template v-for="(event, at) in events" :key="at">
      <!-- event -->
      <li
        :class="styles.event"
        :data-tone="event.tone === undefined || event.tone === 'neutral' ? undefined : event.tone"
      >
        <!-- marker -->
        <span :class="styles.marker" aria-hidden="true">
          <!-- mark -->
          <span :class="styles.mark" :data-mark="event.icon === undefined ? 'dot' : 'icon'">
            <Icon v-if="event.icon !== undefined" :name="event.icon" size="sm" />
          </span>
        </span>
        <!-- copy -->
        <span :class="styles.copy">
          <!-- title -->
          <span :class="styles.title">
            {{ event.title }}
          </span>
          <!-- time -->
          <span :class="styles.time">
            {{ event.time }}
          </span>
          <!-- detail -->
          <span v-if="event.detail !== undefined" :class="styles.detail">
            {{ event.detail }}
          </span>
        </span>
      </li>
    </template>
  </ol>
</template>
